class Solution {
  public int[] digitWorkshopProofStrip(int[] readings) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int x:a){x=Math.abs(x);int s=0;while(x>0){s+=x%10;x/=10;}out.add(s);}}
    return out.stream().mapToInt(Integer::intValue).toArray();
  }
}
